package com.talkbot.plugin.commands;
import com.talkbot.plugin.TalkBotPlugin;import com.talkbot.plugin.manager.ChatManager;import com.talkbot.plugin.manager.BotRegistry;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class TalkBotCommand implements CommandExecutor,TabCompleter {
 private final TalkBotPlugin plugin;private final BotRegistry registry;private final ChatManager chat;
 public TalkBotCommand(TalkBotPlugin p,BotRegistry r,ChatManager c){plugin=p;registry=r;chat=c;}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!s.hasPermission("talkbot.admin")){s.sendMessage("You don't have permission.");return true;}if(a.length==0)return usage(s);switch(a[0].toLowerCase(Locale.ROOT)){case "register"->{if(a.length<2)return usage(s);s.sendMessage(registry.registerBot(a[1])?"Registered "+a[1]:"Could not register bot.");}case "unregister"->{if(a.length<2)return usage(s);s.sendMessage(registry.unregisterBot(a[1])?"Unregistered "+a[1]:"Bot not registered.");}case "list"->{s.sendMessage("Registered bots: "+registry.getRegisteredBots());}case "style"->{if(a.length<3)return usage(s);if(!ChatManager.styles().contains(a[2].toLowerCase(Locale.ROOT))){s.sendMessage("Styles: "+ChatManager.styles());return true;}if(!registry.isBot(a[1])){s.sendMessage("Register that bot first.");return true;}s.sendMessage(registry.setStyle(a[1],a[2].toLowerCase(Locale.ROOT))?a[1]+" style set to "+a[2]:"Could not save style.");}case "reload"->{plugin.reloadConfig();registry.reload();chat.reload();s.sendMessage("TalkBot config reloaded.");}case "status"->{s.sendMessage("Registered bots: "+registry.getRegisteredBots().size()+" | AI enabled: "+plugin.getConfig().getBoolean("ai.enabled"));}case "test"->{if(a.length<2)return usage(s);Player p=Bukkit.getPlayerExact(a[1]);if(p==null){s.sendMessage("No online Bukkit player: "+a[1]);return true;}s.sendMessage("Found "+p.getName()+" ("+p.getClass().getName()+")");if(a.length>2&&a[2].equalsIgnoreCase("confirm")){p.chat("TalkBot diagnostic message");s.sendMessage("Player#chat called; check global chat.");}}default->{return usage(s);}}return true;}
 private boolean usage(CommandSender s){s.sendMessage("/talkbot <register|unregister|list|style <bot> <style>|reload|test|status>");return true;}
 public List<String> onTabComplete(CommandSender s,Command c,String l,String[] a){if(a.length==1)return List.of("register","unregister","list","style","reload","test","status");if(a.length==2&&(a[0].equalsIgnoreCase("unregister")||a[0].equalsIgnoreCase("test")||a[0].equalsIgnoreCase("style")))return new ArrayList<>(registry.getRegisteredBots());if(a.length==3&&a[0].equalsIgnoreCase("style"))return new ArrayList<>(ChatManager.styles());return List.of();}
}
